#pragma once
#include "linalg_internal.hpp"
#include <lapacke.h>
namespace penta::linalg {
inline std::vector<double> copyReal(const penta_linalg_matrix_v1& a){return a.count?std::vector<double>(a.values,a.values+a.count):std::vector<double>();}
// Row-major LAPACKE requires ldvt>=n even with jobz=N. The unused scalar
// remains a legal dummy; supplying its logical leading dimension does not
// request or allocate singular vectors. This works with stricter Linux LAPACKE.
inline std::vector<double> singularValues(const penta_linalg_matrix_v1& a){const auto r=std::min(a.rows,a.columns);std::vector<double> singular(r);if(!r)return singular;auto work=copyReal(a);double dummy=0;lapackStatus(LAPACKE_dgesdd(LAPACK_ROW_MAJOR,'N',static_cast<lapack_int>(a.rows),static_cast<lapack_int>(a.columns),work.data(),static_cast<lapack_int>(a.columns),singular.data(),&dummy,1,&dummy,static_cast<lapack_int>(a.columns)),"SVD condition estimate");return singular;}
inline void conditionFromSingular(const std::vector<double>& singular,const penta_linalg_matrix_v1& a,const penta_linalg_request_v1& request,penta_linalg_result_v1& result){if(singular.empty()){result.rank=0;result.rcond=1;return;}const double cutoff=singular.front()*(request.rank_tolerance>0?request.rank_tolerance:64*std::numeric_limits<double>::epsilon()*std::max(a.rows,a.columns));result.rank=static_cast<uint64_t>(std::count_if(singular.begin(),singular.end(),[&](double x){return x>cutoff;}));result.rcond=singular.front()?singular.back()/singular.front():0;}
inline void condition(const penta_linalg_matrix_v1& a,const penta_linalg_request_v1& request,penta_linalg_result_v1& result){conditionFromSingular(singularValues(a),a,request,result);}
inline void guardedSquare(const penta_linalg_matrix_v1& a,const penta_linalg_request_v1& request,const penta_linalg_result_v1& result){require(a.rows==a.columns,"This solve/inverse requires a square matrix.");if(result.rank<a.columns||result.rcond<request.rcond_min)throw Error(PENTA_NUMERIC_DOMAIN,"Matrix is rank deficient or below the configured reciprocal-condition threshold.");}
inline void symmetric(const penta_linalg_matrix_v1& a){require(a.rows==a.columns,"Cholesky requires a square matrix.");double scale=1;for(uint64_t n=0;n<a.count;++n)scale=std::max(scale,std::abs(a.values[n]));for(uint64_t i=0;i<a.rows;++i)for(uint64_t j=0;j<i;++j)require(std::abs(a.values[i*a.columns+j]-a.values[j*a.columns+i])<=256*std::numeric_limits<double>::epsilon()*scale,"Cholesky requires a symmetric real matrix.");}
inline void residual(const penta_linalg_matrix_v1& a,const penta_linalg_matrix_v1& b,const std::vector<double>& x,penta_linalg_result_v1& result){long double aa=0,bb=0,xx=0,rr=0;for(uint64_t n=0;n<a.count;++n)aa+=static_cast<long double>(a.values[n])*a.values[n];for(uint64_t n=0;n<b.count;++n)bb+=static_cast<long double>(b.values[n])*b.values[n];for(const auto value:x)xx+=static_cast<long double>(value)*value;for(uint64_t i=0;i<a.rows;++i)for(uint64_t j=0;j<b.columns;++j){long double value=-b.values[i*b.columns+j];for(uint64_t k=0;k<a.columns;++k)value+=static_cast<long double>(a.values[i*a.columns+k])*x[k*b.columns+j];rr+=value*value;}result.residual_norm=finite(static_cast<double>(std::sqrt(rr)));const long double denominator=std::sqrt(aa)*std::sqrt(xx)+std::sqrt(bb);result.relative_residual=finite(static_cast<double>(denominator?std::sqrt(rr)/denominator:std::sqrt(rr)));}
}
